const input = $input.item.json;
const serieDiaria = input.serieDiaria || [];
const competenciaResumen = input.competenciaResumen || null;

const habitaciones_totales = input.contextoNegocioSerie?.[0]?.CAPACIDAD_HOTEL || input.habitaciones_totales || 75;

// ==========================================
// 1. REGLAS Y UMBRALES DE NEGOCIO
// ==========================================
const REGLAS_OCUPACION = [
  { min: 0,   max: 40,  estado: "Muy baja", riesgo: "Alto" },
  { min: 40,  max: 60,  estado: "Baja",     riesgo: "Medio" },
  { min: 60,  max: 80,  estado: "Media",    riesgo: "Bajo" },
  { min: 80,  max: 90,  estado: "Alta",     riesgo: "Muy bajo" },
  { min: 90,  max: 999, estado: "Muy alta", riesgo: "Lleno" }
];

const REGLAS_REVPAR = [
  { min: 0,   max: 40,   clasificacion: "Muy bajo" },
  { min: 40,  max: 70,   clasificacion: "Bajo" },
  { min: 70,  max: 100,  clasificacion: "Normal" },
  { min: 100, max: 130,  clasificacion: "Bueno" },
  { min: 130, max: 9999, clasificacion: "Excelente" }
];

const REGLAS_PICKUP = [
  { min: 0,  max: 3,   estado: "Muy bajo" },
  { min: 3,  max: 6,   estado: "Bajo" },
  { min: 6,  max: 10,  estado: "Normal" },
  { min: 10, max: 15,  estado: "Alto" },
  { min: 15, max: 999, estado: "Muy alto" }
];

const REGLAS_PACE = [
  { min: 0,   max: 0.7, estado: "Muy retrasado" },
  { min: 0.7, max: 0.9, estado: "Retrasado" },
  { min: 0.9, max: 1.1, estado: "Normal" },
  { min: 1.1, max: 1.3, estado: "Adelantado" },
  { min: 1.3, max: 999, estado: "Muy adelantado" }
];

const REGLAS_RIESGO_OCUPACION_BAJA = [
  { min: 0,  max: 50,  riesgo: "Alto" },
  { min: 50, max: 70,  riesgo: "Medio" },
  { min: 70, max: 999, riesgo: "Bajo" }
];

// ==========================================
// 2. CONFIGURACIÓN DE PRICING DINÁMICO
// ==========================================
const FACTOR_OCUPACION_PRICING = [
  { min: 0,  max: 40,  factor: 0.90 },
  { min: 40, max: 60,  factor: 0.97 },
  { min: 60, max: 80,  factor: 1.00 },
  { min: 80, max: 90,  factor: 1.10 },
  { min: 90, max: 999, factor: 1.20 }
];

const FACTOR_PACE_PRICING = [
  { min: 0,   max: 0.7, factor: 0.95 },
  { min: 0.7, max: 0.9, factor: 0.98 },
  { min: 0.9, max: 1.1, factor: 1.00 },
  { min: 1.1, max: 1.3, factor: 1.03 },
  { min: 1.3, max: 999, factor: 1.06 }
];

const FACTORES_CANAL = {
  "Booking": 1.05,
  "Expedia": 1.05,
  "Web": 0.95,
  "Teléfono": 1.00,
  "Walk-in": 1.10,
  "Otros": 1.00
};

const FACTORES_TIPO = {
  "Individual": 0.80,
  "Doble": 1.00,
  "Suite": 1.40,
  "Otros": 1.00
};

const FACTORES_PAIS = {
  "España": 1.00,
  "Reino Unido": 1.05,
  "Francia": 1.03,
  "EEUU": 1.10,
  "Italia": 1.00,
  "Portugal": 0.98,
  "Otros": 1.00
};

const BONUS_FESTIVO = 1.10;
const BONUS_VACACIONES = 1.05;
const TECHO_AJUSTE = 1.35;
const SUELO_AJUSTE = 0.75;

// ==========================================
// 3. FUNCIONES AUXILIARES
// ==========================================
function buscarRegla(reglas, valor) {
  return reglas.find(r => valor >= r.min && valor < r.max) || null;
}

function media(arr) {
  const validos = arr.filter(v => typeof v === 'number' && !isNaN(v));
  return validos.length ? validos.reduce((a, b) => a + b, 0) / validos.length : 0;
}

function distribucion(arr) {
  const valores = arr.filter(v => v !== null && v !== undefined);
  if (!valores.length) return [];
  const counts = {};
  valores.forEach(v => { counts[v] = (counts[v] || 0) + 1; });
  return Object.entries(counts)
    .map(([valor, dias]) => ({ valor, dias, pct: Number(((dias / valores.length) * 100).toFixed(1)) }))
    .sort((a, b) => b.dias - a.dias);
}

function calcularSegmentacionPricing(detalle, factores, adrBase, factorTotal) {
  const res = {};
  Object.keys(factores).forEach(clave => {
    const d = detalle?.[clave];
    if (d && d.adr_medio > 0) {
      res[clave] = {
        adr_sugerido: Number((d.adr_medio * factorTotal).toFixed(2)),
        adr_observado: d.adr_medio,
        habitaciones_vendidas: d.habitaciones_vendidas,
        fuente: "datos_reales"
      };
    } else {
      res[clave] = {
        adr_sugerido: Number((adrBase * (factores[clave] ?? 1.0)).toFixed(2)),
        adr_observado: null,
        habitaciones_vendidas: 0,
        fuente: "factor_estimado"
      };
    }
  });
  return res;
}

function calcularPricingDinamico(dia) {
  const adrReferencia = dia.adr_anio_anterior > 0 ? dia.adr_anio_anterior : dia.adr;

  const fOcup = buscarRegla(FACTOR_OCUPACION_PRICING, dia.ocupacion_prevista)?.factor ?? 1.0;
  const fPace = dia.ritmo_pickup !== null
    ? (buscarRegla(FACTOR_PACE_PRICING, dia.ritmo_pickup)?.factor ?? 1.0)
    : 1.0;
  const fEstacional = (dia.es_festivo ? BONUS_FESTIVO : 1) * (dia.es_vacaciones_escolares ? BONUS_VACACIONES : 1);

  let factorTotal = fOcup * fPace * fEstacional;
  const limiteAlcanzado = factorTotal > TECHO_AJUSTE || factorTotal < SUELO_AJUSTE;
  factorTotal = Math.min(Math.max(factorTotal, SUELO_AJUSTE), TECHO_AJUSTE);

  const adrSugeridoBase = Number((adrReferencia * factorTotal).toFixed(2));

  return {
    adr_referencia: Number(adrReferencia.toFixed(2)),
    factor_ocupacion: fOcup,
    factor_pace: fPace,
    factor_estacional: Number(fEstacional.toFixed(2)),
    factor_total_aplicado: Number(factorTotal.toFixed(3)),
    ajuste_pct: Number(((factorTotal - 1) * 100).toFixed(1)),
    adr_sugerido: adrSugeridoBase,
    limite_alcanzado: limiteAlcanzado,
    pricing_por_canal: calcularSegmentacionPricing(dia.canal_detalle, FACTORES_CANAL, adrSugeridoBase, factorTotal),
    pricing_por_tipo: calcularSegmentacionPricing(dia.tipo_detalle, FACTORES_TIPO, adrSugeridoBase, factorTotal),
    pricing_por_pais: calcularSegmentacionPricing(dia.pais_detalle, FACTORES_PAIS, adrSugeridoBase, factorTotal)
  };
}

// ==========================================
// 4. PROCESAMIENTO DIARIO
// ==========================================
function calcularDia(dia) {
  const {
    fecha, ocupacion_actual, ocupacion_prevista, adr, ocupacion_anio_anterior, adr_anio_anterior,
    sin_dato_historico_yoy, pickup_7, pickup_14, ritmo_pickup, estancia_media_noches,
    es_festivo, es_vacaciones_escolares, clima,
    canal_moda, tipo_moda, pais_moda,
    canal_detalle, pais_detalle, tipo_detalle
  } = dia;

  const pricingDinamico = calcularPricingDinamico(dia);

  const pct_ocupacion = ocupacion_prevista / 100;
  const habitaciones_ocupadas = Math.round(pct_ocupacion * habitaciones_totales);
  const habitaciones_libres = habitaciones_totales - habitaciones_ocupadas;
  const incremento_pp = Number((ocupacion_prevista - ocupacion_actual).toFixed(1));
  const reglaOcup = buscarRegla(REGLAS_OCUPACION, ocupacion_prevista);

  const ocupacionBlock = {
    actual: ocupacion_actual,
    prevista: ocupacion_prevista,
    incremento_pp,
    habitaciones_ocupadas,
    habitaciones_libres,
    estado: reglaOcup?.estado ?? "Sin clasificar",
    anio_anterior: ocupacion_anio_anterior,
    sin_dato_historico_yoy: sin_dato_historico_yoy ?? true
  };

  const revpar = Number((pct_ocupacion * adr).toFixed(2));
  const ingresos_previstos = Number((revpar * habitaciones_totales).toFixed(2));
  const revpar_actual = Number(((ocupacion_actual / 100) * adr).toFixed(2));
  const ingresos_actuales = Number((revpar_actual * habitaciones_totales).toFixed(2));
  const reglaRevpar = buscarRegla(REGLAS_REVPAR, revpar);

  const ingresosBlock = {
    adr,
    revpar,
    ingresos_previstos,
    revpar_actual,
    ingresos_actuales,
    adr_anio_anterior,
    clasificacion: reglaRevpar?.clasificacion ?? "Sin clasificar"
  };

  const hayComp = ocupacion_anio_anterior > 0 && adr_anio_anterior > 0;
  let comparativas = null;
  if (hayComp) {
    const revparAA = (ocupacion_anio_anterior / 100) * adr_anio_anterior;
    comparativas = {
      ocupacion_yoy_pp: Number((ocupacion_prevista - ocupacion_anio_anterior).toFixed(1)),
      adr_yoy_pct: Number((((adr - adr_anio_anterior) / adr_anio_anterior) * 100).toFixed(1)),
      revpar_yoy_pct: Number((((revpar - revparAA) / revparAA) * 100).toFixed(1))
    };
  }

  const reglaPickup = pickup_7 !== null ? buscarRegla(REGLAS_PICKUP, pickup_7) : null;
  const reglaPace = ritmo_pickup !== null ? buscarRegla(REGLAS_PACE, ritmo_pickup) : null;

  const pickupPaceBlock = {
    pickup_7,
    pickup_14,
    estado_pickup: reglaPickup?.estado ?? "Sin datos",
    ritmo_pickup,
    estado_pace: reglaPace?.estado ?? "Sin datos",
    estancia_media_noches
  };

  const contextoBlock = { es_festivo, es_vacaciones_escolares, clima };

  const perfilDemandaBlock = {
    canal: canal_moda ?? null,
    tipo: tipo_moda ?? null,
    pais: pais_moda ?? null,
    canal_detalle: canal_detalle ?? null,
    pais_detalle: pais_detalle ?? null,
    tipo_detalle: tipo_detalle ?? null
  };

  const reglaRiesgoOcup = buscarRegla(REGLAS_RIESGO_OCUPACION_BAJA, ocupacion_prevista);
  const riesgosBlock = {
    ocupacion_baja: reglaRiesgoOcup?.riesgo ?? "Sin clasificar",
    ritmo_reserva_debil: (reglaPickup?.estado === "Muy bajo" || reglaPickup?.estado === "Bajo") ? "Alerta" : "Normal"
  };

  const calidadDatos = {
    ocupacion: ocupacion_prevista > 0,
    adr: adr > 0,
    comparativas: hayComp,
    pickup: pickup_7 !== null,
    clima: clima !== null
  };

  return {
    fecha,
    ocupacion: ocupacionBlock,
    ingresos: ingresosBlock,
    comparativas,
    pickup_pace: pickupPaceBlock,
    contexto_externo: contextoBlock,
    perfil_demanda: perfilDemandaBlock,
    riesgos: riesgosBlock,
    calidad_datos: calidadDatos,
    pricing_dinamico: pricingDinamico
  };
}

const metricasDiarias = serieDiaria.map(calcularDia);

// ==========================================
// 5. CÁLCULO DE TOTALES Y AGREGADOS
// ==========================================
const ocupActualMedia = media(serieDiaria.map(d => d.ocupacion_actual));
const ocupPrevistaMedia = media(serieDiaria.map(d => d.ocupacion_prevista));
const adrMedio = media(serieDiaria.map(d => d.adr));
const ingresosTotales = metricasDiarias.reduce((s, d) => s + d.ingresos.ingresos_previstos, 0);
const ingresosActualesTotales = metricasDiarias.reduce((s, d) => s + d.ingresos.ingresos_actuales, 0);

const ocupAAMedia = media(serieDiaria.map(d => d.ocupacion_anio_anterior).filter(v => v !== null));
const adrAAMedia = media(serieDiaria.map(d => d.adr_anio_anterior).filter(v => v !== null));
const hayCompTotal = ocupAAMedia > 0 && adrAAMedia > 0;
const revparMedio = Number(((ocupPrevistaMedia / 100) * adrMedio).toFixed(2));

const revparAATotal = hayCompTotal ? (ocupAAMedia / 100) * adrAAMedia : null;
const ingresosTotalesAnioAnterior = revparAATotal !== null
  ? Number((revparAATotal * habitaciones_totales * serieDiaria.length).toFixed(2))
  : null;
const ingresosYoyPct = (ingresosTotalesAnioAnterior !== null && ingresosTotalesAnioAnterior > 0)
  ? Number((((ingresosTotales - ingresosTotalesAnioAnterior) / ingresosTotalesAnioAnterior) * 100).toFixed(1))
  : null;

let comparativasTotal = null;
if (hayCompTotal) {
  comparativasTotal = {
    ocupacion_yoy_pp: Number((ocupPrevistaMedia - ocupAAMedia).toFixed(1)),
    adr_yoy_pct: Number((((adrMedio - adrAAMedia) / adrAAMedia) * 100).toFixed(1)),
    revpar_yoy_pct: Number((((revparMedio - revparAATotal) / revparAATotal) * 100).toFixed(1)),
    ingresos_yoy_pct: ingresosYoyPct
  };
}

const pickup7Medio = media(serieDiaria.map(d => d.pickup_7).filter(v => v !== null));
const ritmoPickupMedio = media(serieDiaria.map(d => d.ritmo_pickup).filter(v => v !== null));
const diasFestivos = serieDiaria.filter(d => d.es_festivo).length;
const diasVacaciones = serieDiaria.filter(d => d.es_vacaciones_escolares).length;
const diasSinDatoYoy = serieDiaria.filter(d => d.sin_dato_historico_yoy).length;

const perfilDemandaTotal = {
  canal: distribucion(serieDiaria.map(d => d.canal_moda)),
  tipo: distribucion(serieDiaria.map(d => d.tipo_moda)),
  pais: distribucion(serieDiaria.map(d => d.pais_moda))
};

let competenciaBlock = null;
if (competenciaResumen && competenciaResumen.ratingMedioZona) {
  competenciaBlock = {
    rating_medio_zona: competenciaResumen.ratingMedioZona,
    precio_medio_zona: competenciaResumen.precioMedioZona ?? null,
    num_competidores: competenciaResumen.numCompetidores,
    posicionamiento: competenciaResumen.ratingMedioZona >= 4.2 ? "Zona de alta reputación" : "Zona de reputación media",
    datos_actualizados: !competenciaResumen.usando_datos_antiguos,
    hoteles: (competenciaResumen.hoteles || [])
      .slice()
      .sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0))
      .slice(0, 10)
  };
}

const adrSugeridoMedio = media(metricasDiarias.map(d => d.pricing_dinamico?.adr_sugerido));
const ajustePctMedio = media(metricasDiarias.map(d => d.pricing_dinamico?.ajuste_pct));
const diasEnLimite = metricasDiarias.filter(d => d.pricing_dinamico?.limite_alcanzado).length;

const pricingDinamicoTotal = {
  adr_sugerido_medio: Number(adrSugeridoMedio.toFixed(2)),
  ajuste_pct_medio: Number(ajustePctMedio.toFixed(1)),
  dias_con_limite_alcanzado: diasEnLimite
};

const totalPeriodo = {
  dias_analizados: serieDiaria.length,
  ocupacion: {
    actual_media: Number(ocupActualMedia.toFixed(4)),
    prevista_media: Number(ocupPrevistaMedia.toFixed(4)),
    anio_anterior_media: hayCompTotal ? Number(ocupAAMedia.toFixed(4)) : null,
    estado: buscarRegla(REGLAS_OCUPACION, ocupPrevistaMedia)?.estado ?? "Sin clasificar"
  },
  ingresos: {
    adr_medio: Number(adrMedio.toFixed(2)),
    revpar_medio: revparMedio,
    ingresos_totales_previstos: Number(ingresosTotales.toFixed(2)),
    ingresos_totales_actuales: Number(ingresosActualesTotales.toFixed(2)),
    ingresos_totales_anio_anterior: ingresosTotalesAnioAnterior,
    clasificacion: buscarRegla(REGLAS_REVPAR, revparMedio)?.clasificacion ?? "Sin clasificar"
  },
  comparativas: comparativasTotal,
  pickup_pace: {
    pickup_7_medio: Number(pickup7Medio.toFixed(1)),
    ritmo_pickup_medio: Number(ritmoPickupMedio.toFixed(2)),
    estado_pace: buscarRegla(REGLAS_PACE, ritmoPickupMedio)?.estado ?? "Sin datos"
  },
  contexto_externo: {
    dias_festivos: diasFestivos,
    dias_vacaciones_escolares: diasVacaciones,
    dias_sin_dato_historico_yoy: diasSinDatoYoy
  },
  perfil_demanda: perfilDemandaTotal,
  competencia: competenciaBlock,
  pricing_dinamico: pricingDinamicoTotal
};

// ==========================================
// 6. RETORNO DE SALIDA
// ==========================================
return [{ json: { calculo_metricas: { total: totalPeriodo, diario: metricasDiarias } } }];
